class Solution:
    def minNumberOfHours(self, initialEnergy: int, initialExperience: int, energy: list[int], experience: list[int]) -> int:
        req_energy = max(0, sum(energy) + 1 - initialEnergy)
        cur_exp = initialExperience
        req_exp = 0
        for e in experience:
            if cur_exp <= e:
                needed = e + 1 - cur_exp
                req_exp += needed
                cur_exp += needed
            cur_exp += e
        return req_energy + req_exp

class Solution {
public:
    int minNumberOfHours(int initialEnergy, int initialExperience, std::vector<int>& energy, std::vector<int>& experience) {
        int total_energy = 0;
        for (int e : energy) total_energy += e;
        int req_energy = std::max(0, total_energy + 1 - initialEnergy);
        int cur_exp = initialExperience, req_exp = 0;
        for (int e : experience) {
            if (cur_exp <= e) {
                int needed = e + 1 - cur_exp;
                req_exp += needed;
                cur_exp += needed;
            }
            cur_exp += e;
        }
        return req_energy + req_exp;
    }
};

